const DAY=24*60*60*1e3;function byKeyThenDate(a,b){if(a.key!==b.key)return a.key<b.key?-1:1;return a.date-b.date}function monthIndex(d){return d.getFullYear()*12+d.getMonth()}function lineData(data,{daily=false}={}){const sorted=[...data].sort(byKeyThenDate);if(daily)return sorted;const out=[];sorted.forEach((d,i)=>{const prev=sorted[i-1];if(prev?.key===d.key){for(let m=monthIndex(prev.date)+1;m<monthIndex(d.date);m++){out.push({key:d.key,date:new Date(Math.floor(m/12),m%12,1),value:null})}}out.push(d)});return out}function trailingAverage(data,days){const out=[];const sorted=data.filter(d=>d.value!=null).sort(byKeyThenDate);let first=0;let start=0;let sum=0;sorted.forEach((d,i)=>{if(sorted[first].key!==d.key){first=start=i;sum=0}sum+=d.value;while(daysBetween(sorted[start].date,d.date)>=days)sum-=sorted[start++].value;if(daysBetween(sorted[first].date,d.date)>=days-1)out.push({...d,value:sum/(i-start+1)})});return out}function daysBetween(a,b){return Math.round((b-a)/DAY)}function wrapLabel(text,maxWidth,measure){const lines=[];for(const word of text.split(" ")){const last=lines[lines.length-1];if(last!=null&&measure(`${last} ${word}`)<=maxWidth)lines[lines.length-1]=`${last} ${word}`;else lines.push(word)}return lines}function dodge(items,{gap,top,bottom}){const half=item=>item.lines*gap/2;const py=items.map(item=>item.py);for(let i=0;i<py.length;i++){const floor=i===0?top+half(items[0]):py[i-1]+half(items[i-1])+half(items[i]);py[i]=Math.max(py[i],floor)}for(let i=py.length-1;i>=0;i--){const ceiling=i===py.length-1?bottom-half(items[i]):py[i+1]-half(items[i+1])-half(items[i]);py[i]=Math.min(py[i],ceiling)}return py}function placeNotes(notes,{left=0,right,measure,taken=0,offset=4,pad=8}){const rowEnds=[taken];return[...notes].sort((a,b)=>a.px-b.px).map(note=>{const width=measure(note.text);let from=note.px+offset;if(from+width>right)from=note.px-offset-width;from=Math.max(left,Math.min(from,right-width));let row=rowEnds.findIndex(end=>from>end+pad);if(row===-1)row=rowEnds.length;rowEnds[row]=from+width;return{...note,row,dx:from-note.px}})}export{dodge,lineData,placeNotes,trailingAverage,wrapLabel};
